Definition scU8_post (sp gp tp : word) (F : bvmap 5 word) (fc : bv 32) (LB : list block) (LF : list fframe)
    (S ioc regb cfgb lo shi spa ff fp : Z) (xa0 xs2 xs3 xs7 xs9 errv : word) (p16 p24 : list byte) (cs1 : list cell) (m : mem) : machine_state -> Prop :=
  fun ms' => exists t0 t1 t2 a5 a6 a7 t3 t4 t5 t6 m' j256,
    ms' = MS (mkR (Z_to_bv 64 P_A_SC_CG6R) (Z_to_bv 64 spa) gp tp t0 t1 t2 sp (Z_to_bv 64 spa)
                  (wz cfgb) (wz AL_STR_SCHEDULER) (wz (akey_lit KWait)) (wz 18446744073709551615) (wz 0) a5 a6 a7
                  xs2 xs3 (Z_to_bv 64 S) (Z_to_bv 64 (Z.shiftr (ioc + 8) 3 + 2147450880)) (Z_to_bv 64 AL_TYPEID_CONFIG) xs7
                  (Z_to_bv 64 (ioc + 8)) xs9 (Z_to_bv 64 ff) (Z_to_bv 64 2147450880) t3 t4 t5 t6)
             F (Z_to_bv 64 P_A_CONFIG_GET_LONG) fc None m' (seg_rom asegs)
    /\ munch (sc_W3 lo spa S regb) m m' /\ wmono asegs m m' /\ mem_inv asegs m'
    /\ stk asegs m' lo spa
    /\ rw_cells asegs m' spa (sc_loc p16 p24 ff)
    /\ rw_cells asegs m' S (cs1 ++ [C8 xa0; CB 16 j256])
    /\ addressable m' S NEWSZ_SCH
    /\ asc_inv LB m' ioc regb cfgb errv
