Lemma sc_U8 : forall (LB : list block) (LF : list fframe) (S ioc regb cfgb lo shi spa ff fp : Z) (sp tp : word) (errv : word)
    (p16 p24 j248 : list byte) (cs1 : list cell) (m : mem)
    (rax gp t0 t1 t2 xa0 a1 a2 a3 a4 a5 a6 a7 xs2 xs3 xs7 xs9 t3 t4 t5 t6 : word) (F : bvmap 5 word) (fc : bv 32),
  rw_cells asegs m spa (sc_loc p16 p24 ff) ->
  rw_cells asegs m S (cs1 ++ [CB 24 j248]) -> Z.of_nat (cells_size cs1) = 248 -> addressable m S NEWSZ_SCH ->
  stk asegs m lo spa -> mem_inv asegs m ->
  asc_inv LB m ioc regb cfgb errv ->
  as_RFS H ((3, ff, fp) :: LF) m -> ACONST m -> stack0 m lo shi ->
  sc_side H LB LF S ioc regb cfgb lo shi spa ff fp sp tp ->
  evt asegs (scU8_post sp gp tp F fc LB LF S ioc regb cfgb lo shi spa ff fp xa0 xs2 xs3 xs7 xs9 errv p16 p24 cs1 m)
    (MS (mkR rax (Z_to_bv 64 spa) gp tp t0 t1 t2 sp (Z_to_bv 64 spa) xa0 a1 a2 a3 a4 a5 a6 a7
             xs2 xs3 (Z_to_bv 64 S) (Z_to_bv 64 (Z.shiftr (ioc + 8) 3 + 2147450880)) (Z_to_bv 64 AL_TYPEID_CONFIG) xs7
             (Z_to_bv 64 (ioc + 8)) xs9 (Z_to_bv 64 ff) (Z_to_bv 64 2147450880) t3 t4 t5 t6)
        F (Z_to_bv 64 P_A_SC_CG5R) fc None m (seg_rom asegs)).
